"""Kiểm tra Chrome thật, PG local tách biệt. Firebase/AI demo và player mock ghi rõ."""
import asyncio,json,os,sys
import websockets,psycopg
import browser_smoke as h
from postgres_fixture import LocalPostgres
RESULTS=[]
def passed(name):
    RESULTS.append(name);print('PASS '+name,flush=True)
    (h.ARTIFACTS/'stories31-browser.json').write_text(json.dumps({'checks':RESULTS,'firebase':'fixture','ai':'demo','youtube':'player lifecycle fixture, live check separate'},ensure_ascii=False,indent=2),encoding='utf8')

async def checks(url,origin):
    async with websockets.connect(url,origin='http://localhost:9227',max_size=20000000) as ws:
        b=h.Browser(ws);await b.call('Runtime.enable');await b.call('Page.enable')
        await b.call('Emulation.setDeviceMetricsOverride',{'width':1440,'height':1000,'deviceScaleFactor':1,'mobile':False})
        await b.call('Page.addScriptToEvaluateOnNewDocument',{'source':"""
window.requests31=[];const savedFetch=fetch;fetch=(url,options={})=>{requests31.push({url:String(url),method:options.method||'GET',body:options.body||''});return savedFetch(url,options);};
"""})
        await b.call('Page.navigate',{'url':origin+'/mot-ngay-lam-viec'})
        await b.wait_for("document.querySelector('#story-library')?.hidden===false")
        assert await b.evaluate("document.querySelectorAll('.story-card').length===12 && document.querySelectorAll('#story-category-filter option').length===13 && requests31.length===1 && !document.querySelector('iframe')")
        assert await b.evaluate("getComputedStyle(document.querySelector('#story-grid')).gridTemplateColumns.split(' ').length===3")
        assert await b.evaluate("document.querySelectorAll('.story-card:not(:has(img)) .cover-play').length===0")
        await b.wait_for("[...document.querySelectorAll('#story-grid img')].every(i=>i.complete&&i.naturalWidth>0)")
        await b.screenshot('stories31-library-desktop.png');passed('Library: 12 of 200 cards, 12 groups, 3 columns, no iframes or fake play icons')
        await b.call('Emulation.setDeviceMetricsOverride',{'width':900,'height':1000,'deviceScaleFactor':1,'mobile':False})
        assert await b.evaluate("getComputedStyle(document.querySelector('#story-grid')).gridTemplateColumns.split(' ').length===2 && document.documentElement.scrollWidth<=innerWidth+1")
        await b.screenshot('stories31-library-tablet.png')
        await b.call('Emulation.setDeviceMetricsOverride',{'width':1440,'height':1000,'deviceScaleFactor':1,'mobile':False})
        await b.evaluate("document.querySelector('#story-more').click()")
        assert await b.evaluate("document.querySelectorAll('.story-card').length===24")
        await b.evaluate("document.querySelector('#story-search').value='dieu duong';document.querySelector('#story-filters').requestSubmit()")
        assert await b.evaluate("document.querySelectorAll('.story-card').length===1 && document.querySelector('.story-card h2').textContent==='Điều dưỡng'")
        await b.evaluate("document.querySelector('#story-search').value='Điều dưỡng';document.querySelector('#story-filters').requestSubmit()")
        assert await b.evaluate("document.querySelectorAll('.story-card').length===1")
        await b.evaluate("document.querySelector('#story-search').value='';document.querySelector('#story-filters').requestSubmit();document.querySelector('#story-category-filter').value='design';document.querySelector('#story-category-filter').dispatchEvent(new Event('change'))")
        assert await b.evaluate("document.querySelectorAll('.story-card').length===12 && document.querySelector('#story-count').textContent.includes('18 nghề')")
        passed('Accent-insensitive Vietnamese search, filters and load-more')
        await b.call('Emulation.setDeviceMetricsOverride',{'width':390,'height':844,'deviceScaleFactor':1,'mobile':True})
        assert await b.evaluate("document.documentElement.scrollWidth<=innerWidth+1 && getComputedStyle(document.querySelector('#story-grid')).gridTemplateColumns.split(' ').length===1")
        await b.evaluate("document.querySelector('#story-category-filter').value='';document.querySelector('#story-category-filter').dispatchEvent(new Event('change'))")
        await b.screenshot('stories31-library-mobile.png');passed('Mobile library: one column and no horizontal overflow')
        await b.call('Page.navigate',{'url':origin+'/mot-ngay-lam-viec?nghe=kiem-sat-vien'})
        await b.wait_for("document.querySelector('#story-detail')?.hidden===false")
        assert await b.evaluate("document.querySelector('#career-title').textContent==='Kiểm sát viên' && document.querySelector('#story-library').hidden && document.querySelectorAll('.story-card').length===0 && requests31.length===2")
        assert await b.evaluate("document.querySelector('#tab-comic').getAttribute('aria-selected')==='true' && document.querySelector('#decision-card').hidden && document.querySelector('#day-summary').hidden && !document.querySelector('iframe')")
