        assert await b.evaluate("!document.querySelector('#video-empty').hidden && document.querySelector('#video-content').hidden && !document.querySelector('iframe')")
        await b.evaluate("document.querySelector('#tab-comic').click();document.querySelector('#next-scene').click()")
