        await b.evaluate("document.querySelector('#next-scene').click();document.querySelector('#next-scene').click();document.querySelector('#next-scene').click()")
        assert await b.evaluate("document.querySelector('#scene-counter').textContent==='5 / 5' && document.querySelector('#day-summary').hidden")
        await b.screenshot('stories31-comic-final-scene.png')
        await b.evaluate("document.querySelector('#next-scene').click()")
        assert await b.evaluate("!document.querySelector('#day-summary').hidden && document.querySelector('#comic-reader').hidden")
        await b.screenshot('stories31-summary.png')
        await b.evaluate("document.querySelector('#restart-story').click();document.querySelector('#next-scene').click()")
        assert await b.evaluate("document.querySelector('#scene-counter').textContent==='2 / 5' && document.querySelector('#decision-feedback').hidden")
        passed('Final scene precedes separate summary; replay resets state')
        await b.evaluate("document.querySelector('[data-choice=option-1]').click();document.querySelector('#next-scene').click();document.querySelector('#next-scene').click();document.querySelector('#ask-scene').click();document.querySelector('#story-question').value='Vì sao cần đúng thẩm quyền?';document.querySelector('#story-ask-form').requestSubmit()")
        await b.wait_for("document.querySelector('#career-survey')?.hidden===false && !document.querySelector('#survey-next').disabled",timeout=45)
        for _ in range(5):await b.evaluate("document.querySelector('#survey-suggestions button').click();document.querySelector('#survey-next').click()")
        await b.wait_for("document.querySelector('#message-input').value.includes('scene-4') && document.querySelector('#career-survey').hidden",timeout=45)
        assert await b.evaluate("requests31.every(r=>r.url!='/api/ai/chat') && document.querySelector('#message-input').value.includes('Vì sao cần đúng thẩm quyền')")
